from pathlib import Path
import zlib,base64,hashlib,subprocess,sys,os
s=zlib.decompress(base64.b64decode(''))
assert hashlib.sha256(s).hexdigest()=='6410c46aad97676196722846c6f1ab98629c8a2cf5cffc0770675703b65eb18d'
compile(s,'w06','exec')
p=Path('/home/ec2-user/studies/diet_gut_cgm_v2/multisystem_project_20261021/scripts/w06_food_cleaning_20261028/03_independent_verify.py')
assert not p.exists()
p.write_bytes(s)
assert p.read_bytes()==s
r=Path('/home/ec2-user/multisystem_runtime_20261021/w06_food_cleaning_20261028')
runner=r/'03_runner.py'
runner.write_text('import subprocess,sys,pathlib\nr=pathlib.Path('+repr(str(r))+')\nf=(r/"03.log").open("w")\nc=subprocess.run([sys.executable,"-u",'+repr(str(p))+'],stdout=f,stderr=subprocess.STDOUT)\nf.close()\n(r/"03_actual_exit_code").write_text(str(c.returncode))\n')
