f=(r/'03_launcher.log').open('w')
c=subprocess.Popen([sys.executable,'-u',str(runner)],stdout=f,stderr=subprocess.STDOUT,start_new_session=True,env=e)
f.close()
(r/'03_pid').write_text(str(c.pid))
print('W06_LAUNCHED',c.pid,'SOURCE_SHA',hashlib.sha256(p.read_bytes()).hexdigest())
